import networkx as nx
import random

def find_graph():
    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(21))
        edges = []
        while len(edges) < 40:
            u = random.randint(0, 20)
            v = random.randint(0, 20)
            if u != v and not G.has_edge(u, v):
                G.add_edge(u, v)
                if nx.girth(G) < 8:
                    G.remove_edge(u, v)
                else:
                    edges.append((u, v))

        if len(G.edges()) >= 40:
            # Check 4-colorability
            if nx.coloring.greedy_color(G, strategy='largest_first').values():
                max_color = max(nx.coloring.greedy_color(G, strategy='largest_first').values())
                if max_color < 4:
                    return list(G.edges())
    return None

result = find_graph()
print(result)

def moore_bound(k, g):
    if g % 2 == 1:
        # Odd girth
        d = (g - 1) // 2
        return 1 + k * sum((k - 1)**i for i in range(d))
    else:
        # Even girth
        d = (g - 2) // 2
        return 2 * sum((k - 1)**i for i in range(d + 1))

# Check for k=3, g=8
print(f"Moore bound for k=3, g=8: {moore_bound(3, 8)}")
# Check for k=2, g=8
print(f"Moore bound for k=2, g=8: {moore_bound(2, 8)}")
